import{_ as n,a as o,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 单元 2 语法总结 · 间接引语与视角转换至动名词与动词搭配","description":"L25–L48 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 2 语法总结 · 间接引语与视角转换至动名词与动词搭配","description":"L25–L48 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-02/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 2 语法总结","summary":"L25–L48 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 2 语法总结","link":"/life/english/new-concept/book-2/unit-02/grammar"},"next":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式","link":"/life/english/new-concept/book-2/unit-02/grammar-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 2 语法总结","link":"/life/english/new-concept/book-2/unit-02/grammar"},"next":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式","link":"/life/english/new-concept/book-2/unit-02/grammar-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/grammar-part-01.md","filePath":"life/english/new-concept/book-2/unit-02/grammar-part-01.md"}'),i={name:"life/english/new-concept/book-2/unit-02/grammar-part-01.md"};function r(s,e,l,p,h,d){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-2-语法总结-·-间接引语与视角转换至动名词与动词搭配" tabindex="-1">第二册：实践与进步 · 单元 2 语法总结 · 间接引语与视角转换至动名词与动词搭配 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-语法总结-·-间接引语与视角转换至动名词与动词搭配" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 语法总结 · 间接引语与视角转换至动名词与动词搭配&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-02/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><h2 id="第二册-实践与进步-·-单元-2-语法总结" tabindex="-1">第二册：实践与进步 · 单元 2 语法总结 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-语法总结" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 语法总结 {#第二册-实践与进步-·-单元-2-语法总结}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><h2 id="间接引语与视角转换" tabindex="-1">间接引语与视角转换 <a class="header-anchor" href="#间接引语与视角转换" aria-label="Permalink to &quot;间接引语与视角转换 {#间接引语与视角转换}&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：间接问句保留疑问词 where，但用 the bus stopped 的陈述语序；不能保留直接问句的 did the bus stop。</p><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：told me that it had been found 同时体现转述和过去完成被动。过去参照是通知的时刻，找回先于通知，执行者可不出现。</p><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：是否问句转述用 if/whether，后接陈述语序。asked whether he could leave 表在当时询问许可，不能从这句推断已经获准出院。</p><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：People say that ... 只标记传闻来源，不保证从句真实。was said to be 可使语气保持距离，但仍应说明缺少证据。</p><p><strong>L25 原创例句：</strong> I asked the driver where the bus stopped.</p><p>我问司机这辆公共汽车在哪里停。</p><p><strong>L34 原创例句：</strong> The police told me that my bicycle had been found.</p><p>警方告诉我，我的自行车已被找回。</p><p><strong>L39 原创例句：</strong> Evan asked the nurse whether he could leave that afternoon.</p><p>埃文问护士，他当天下午能否离开。</p><p><strong>L47 原创例句：</strong> The cellar was said to be haunted, but no one had evidence.</p><p>据说地窖闹鬼，但没有人有证据。</p><p><strong>易错：</strong> I asked where did it stop 错误；从句应为 where it stopped。</p><p>police 通常作复数集合名词：The police are investigating，不用 is。</p><p>asked whether could he leave 保留了直接问句倒装，应改为 whether he could leave。</p><p>evidence 通常不可数，不写 an evidence；可说 a piece of evidence。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-025">Lesson 25</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-034">Lesson 34</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-039">Lesson 39</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-047">Lesson 47</a></p><h2 id="一般现在时与习惯" tabindex="-1">一般现在时与习惯 <a class="header-anchor" href="#一般现在时与习惯" aria-label="Permalink to &quot;一般现在时与习惯 {#一般现在时与习惯}&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：understand 和 like 表状态时通常不用进行时；look at 是可持续的动作，可以用 is looking。表达个人审美不要把主观意见写成客观结论。</p><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：used to repair 表过去经常维修，如今情况已改变；be used to repairing 表已经习惯维修，不带同样的过去对照含义。</p><p><strong>L26 原创例句：</strong> My sister likes paintings with strong colours.</p><p>我妹妹喜欢色彩强烈的画。</p><p><strong>L31 原创例句：</strong> Mina used to repair bicycles in her parents&#39; garage.</p><p>米娜过去常在父母的车库里修自行车。</p><p><strong>易错：</strong> She is liking this style 在一般偏好语境下不自然；常用 She likes this style。</p><p>used to repairing 把过去习惯与 be used to doing 混淆；此处应为 used to repair。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-026">Lesson 26</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-031">Lesson 31</a></p><h2 id="过去完成时与先后关系" tabindex="-1">过去完成时与先后关系 <a class="header-anchor" href="#过去完成时与先后关系" aria-label="Permalink to &quot;过去完成时与先后关系 {#过去完成时与先后关系}&quot;">​</a></h2><p>过去完成时由 had 加过去分词构成，表示在另一个过去参照点之前发生的事。必须先建立“过去的那个时刻”，否则不宜只因事件发生得很久以前就使用 had done。before 或 after 已清楚说明先后时，一般过去时也可能成立；过去完成时则进一步强调较早的动作已完成。叙事回到主时间线后通常继续使用一般过去时。本课应用：had covered 早于 woke up，两个时间层次有清楚参照。不能仅因都是昨晚的事就把所有动词写成过去完成时。</p><p>过去完成时由 had 加过去分词构成，表示在另一个过去参照点之前发生的事。必须先建立“过去的那个时刻”，否则不宜只因事件发生得很久以前就使用 had done。before 或 after 已清楚说明先后时，一般过去时也可能成立；过去完成时则进一步强调较早的动作已完成。叙事回到主时间线后通常继续使用一般过去时。本课应用：had lost 表走到岸边之前已经发生的损失。恢复主线后使用 reached、called 等简单过去式，避免全段一律使用 had。</p><p>过去完成时由 had 加过去分词构成，表示在另一个过去参照点之前发生的事。必须先建立“过去的那个时刻”，否则不宜只因事件发生得很久以前就使用 had done。before 或 after 已清楚说明先后时，一般过去时也可能成立；过去完成时则进一步强调较早的动作已完成。叙事回到主时间线后通常继续使用一般过去时。本课应用：had dreamed for years 描述搬家前已经持续多年的愿望；moved 才是叙事的主时间点。for years 不会自动要求现在完成时。</p><p><strong>L27 原创例句：</strong> We had covered the bags before the rain started.</p><p>下雨前，我们已经把包盖好了。</p><p><strong>L33 原创例句：</strong> By the time we reached the shore, we had lost our map.</p><p>到达岸边时，我们已经丢了地图。</p><p><strong>L38 原创例句：</strong> Before he moved north, Joel had dreamed of a quiet village.</p><p>搬到北方之前，乔尔曾向往一个安静的村庄。</p><p><strong>易错：</strong> had went 错误；had 后用过去分词 gone，不能用过去式 went。</p><p>had lost 不表示此后才丢；它把丢地图放在到岸之前。</p><p>dream of live 错误，介词 of 后若接动词应为 living。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-027">Lesson 27</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-033">Lesson 33</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-038">Lesson 38</a></p><h2 id="动名词与动词搭配" tabindex="-1">动名词与动词搭配 <a class="header-anchor" href="#动名词与动词搭配" aria-label="Permalink to &quot;动名词与动词搭配 {#动名词与动词搭配}&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：No parking 是 no 加动名词名词化的告示，不是完整陈述句。改写时可用 You must not park here，禁止意义比请求强。</p><p><strong>L28 原创例句：</strong> Parking beside this gate blocks the entrance.</p><p>在这扇门旁停车会堵住入口。</p><p><strong>易错：</strong> Parking ... block 缺少第三人称单数词尾；一个动名词短语通常按单数看待。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-028">Lesson 28</a></p>',53)])])}const f=n(i,[["render",r]]);export{g as __pageData,f as default};
